<?php declare(strict_types=1); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Free Color Mixer Online','description'=>'Mix two HEX colors and calculate the resulting color instantly.','url'=>'https://smarttoolz.in/tools/color-mixer/']; smarttoolz_tool_page_start($tool); ?><main class="tool-page"><section class="tool-intro"><span class="tool-kicker">COLOR MIXER</span><h1>Color Mixer</h1><p>Mix two colors and get the resulting HEX and RGB values.</p></section><section class="tool-workspace"><div class="tool-panel"><label>Color A<input id="a" type="color" value="#5b43ff"></label><label>Color B<input id="b" type="color" value="#3b82f6"></label><button id="go" class="tool-btn">Mix Colors</button><div id="out" style="margin-top:15px;padding:30px;border-radius:15px;font-weight:800;text-align:center"></div></div></section></main><script>(()=>{const a=document.getElementById('a'),b=document.getElementById('b'),o=document.getElementById('out');document.getElementById('go').onclick=()=>{let A=a.value,B=b.value,c=i=>parseInt(i.slice(1),16),x=c(A),y=c(B),r=Math.round(((x>>16)+(y>>16))/2),g=Math.round((((x>>8)&255)+((y>>8)&255))/2),z=Math.round(((x&255)+(y&255))/2),hex='#'+((r<<16)|(g<<8)|z).toString(16).padStart(6,'0');o.style.background=hex;o.textContent=hex.toUpperCase()}})();document.getElementById('go').click();</script><?php smarttoolz_tool_page_end(); ?>